/* Kazakhstan universities: self-contained logos and a seamless accessible marquee. */
(()=>{
 const universities=[{"name":"Nazarbayev University","url":"https://nu.edu.kz","logo":"data:image/png;base64,"},{"name":"Satbayev University","url":"https://satbayev.university","logo":"data:image/png;base64,"},{"name":"MNU","url":"https://mnu.kz","logo":"data:image/png;base64,"},{"name":"KazNU","url":"https://kaznu.kz","logo":"data:image/png;base64,"},{"name":"ENU","url":"https://enu.kz","logo":"data:image/svg+xml;base64,"},{"name":"Astana IT University","url":"https://astanait.edu.kz","logo":"data:image/png;base64,"},{"name":"KBTU","url":"https://kbtu.edu.kz","logo":"data:image/png;base64,"},{"name":"SDU University","url":"https://sdu.edu.kz","logo":"data:image/png;base64,"},{"name":"KIMEP University","url":"https://kimep.kz","logo":"data:image/png;base64,"}];
 function mount(){
  const welcome=document.querySelector('#welcome');
  if(!welcome||welcome.querySelector('.motivation-loop'))return;
  const anchor=welcome.querySelector('.arch-facts');
  if(!anchor)return;
  const section=document.createElement('section');
  section.className='motivation-loop';
  section.setAttribute('aria-label','Қазақстан университеттері');
  const track=document.createElement('div');track.className='university-marquee-track';
  const group=document.createElement('div');group.className='university-marquee-group';
  universities.forEach(({name,url,logo})=>{
   const link=document.createElement('a');link.className='university-pill';link.href=url;link.target='_blank';link.rel='noopener noreferrer';link.setAttribute('aria-label',name+' — ресми сайт (жаңа бетте ашылады)');
   const badge=document.createElement('span');badge.className='university-logo';
   const image=document.createElement('img');image.src=logo;image.alt='';image.width=40;image.height=40;image.decoding='async';
   const label=document.createElement('span');label.textContent=name;
   badge.append(image);link.append(badge,label);group.append(link);
  });
  const copy=group.cloneNode(true);copy.setAttribute('aria-hidden','true');copy.inert=true;copy.querySelectorAll('a').forEach(link=>link.tabIndex=-1);
  track.append(group,copy);section.append(track);anchor.after(section);
  const observer=new IntersectionObserver(entries=>{track.style.animationPlayState=entries[0].isIntersecting?'':'paused'});
  observer.observe(section);
  section._disposeUniversityMarquee=()=>observer.disconnect();
 }
 let previous=null;
 const refresh=()=>{
  if(previous&&!previous.isConnected){previous._disposeUniversityMarquee?.();previous=null}
  mount();previous=document.querySelector('#welcome .motivation-loop');
 };
 new MutationObserver(refresh).observe(document.body,{subtree:true,childList:true});
 refresh();
})();
